+}
+
+.item {
+  display: grid;
+  gap: 4px;
+  padding: 10px 0;
+  border-bottom: 1px solid var(--thorp-line);
+}
+
+.item:first-child {
+  padding-top: 0;
+}
+
+.item:last-child {
+  padding-bottom: 0;
+  border-bottom: 0;
+}
+
+.itemTitle {
+  color: var(--thorp-foreground);
+  font-size: var(--thorp-text-body, 0.88rem);
+  font-weight: 600;
+  line-height: 1.45;
+  text-decoration: none;
+  word-break: keep-all;
+}
+
+/*
+  고른 섹터·분류 칸. 넓으면 여러 칸이 나란히 서고 좁아지면 접힌다. 칸이 적어도 늘이지 않아(auto-fill) 고른 섹터 칸과 분류 칸이
+  같은 세로줄에 선다.
+*/
+.columns {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
+  gap: 18px 24px;
+}
+
+.column {
+  display: grid;
+  align-content: start;
+  gap: 8px;
+  min-width: 0;
+}
+
+.columnTitle {
+  margin: 0;
+  padding-bottom: 6px;
+  border-bottom: 1px solid var(--thorp-line-strong);
+  color: var(--thorp-accent-soft);
+  font-size: var(--thorp-text-small, 0.8rem);
+  font-weight: 680;
+}
+
+.failure {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: center;
+  gap: 8px 12px;
+  color: var(--thorp-muted);
+  font-size: var(--thorp-text-small, 0.78rem);
+}
+
+.failure p {
+  margin: 0;
+}
+
+.inlineAction {
+  min-height: 28px;
+  padding: 0 10px;
+  border: 1px solid var(--thorp-line-control, var(--thorp-line-strong));
+  border-radius: var(--thorp-radius-control, 6px);
+  background: transparent;
+  color: var(--thorp-foreground);
+  font: inherit;
+  font-size: var(--thorp-text-small, 0.78rem);
+  cursor: pointer;
+}
+
+@media (max-width: 900px) {
+  .leadGrid {
+    grid-template-columns: 1fr;
+  }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  .group,
+  .chip {
+    transition: none;
+  }
+}

